// === Tab: main ===
var pso = undefined;
var circle = undefined;
var minAngle = undefined;
var maxAngle = undefined;
var positions = [];
var particlePositions = [];
var updateIt = 3;
var counter = 1;
var plotter = undefined;
var backgroundPlot = undefined;
var running = false;
var initialized = false;

function setup() {
	createCanvas(windowHeight*4/3, windowHeight);
	backgroundPlot = createGraphics(width, height);
	minAngle = 0;
	maxAngle =  2 * PI;
	circle = new CircleSector(createVector(width/4, height / 4), max(width, height) / 4, minAngle, maxAngle);

	// unused objective functions
	var f1 = (pos) => { return circle.getCenter().sub(pos).mag(); };
	var f2 = (pos) => { 
		var dist = circle.getCenter().sub(pos).mag();
		if(dist > circle.getRadius()){
			return dist;
		}
		else {
			return -dist;
		}
	};

	init();
}

function init() {
	var maxVal = max(width, height) / 2;
	maxVal = 0;
	var minVal = -4*exp(0);

	positions = [];

	for(var i = 0; i < 30; i++) {
		var alpha = 2 * PI * random();
		var len = sqrt(random()) * circle.getRadius();
		var x = circle.getCenter().x + (cos(alpha) * len);
		var y = circle.getCenter().y + (sin(alpha) * len);
		positions.push(createVector(x, y));
	}

	var f3 = (pos) => { 
		var dist = circle.getCenter().sub(pos).mag();
		if(dist > circle.getRadius()){
			return 1000000;
		}
		else {
			var result = 0;
			for(var i = 0; i < positions.length; i++){
				result -= exp(-pos.copy().sub(positions[i]).mag() / 60);
			}
			return result;
		}
	};

	pso = new PSO(f3, circle, minAngle, maxAngle);
	pso.initializeSwarm();	
	plotter = new Plotter(f3, (vec) => circle.contains(vec), minVal, maxVal);
	plotter.draw(backgroundPlot);
	initialized = true;
	running = false;
}

function mouseClicked() {
	if(initialized) {
		if(!running) {
			running = true;
		}
		else {
			init();
		}
	}
  else if(!initialized) {
		init();
	}
}

function draw() {	
	background(0);
	//translate(-50, -50)
	var particles = pso.getParticles();
	var radius = 5;
	image(backgroundPlot, 0, 0);

	fill(100);
	noStroke();
	for(var i = 0; i < positions.length; i++) {
		var pos = positions[i];
		if(circle.contains(pos)) {
			ellipse(pos.x, pos.y, 3, 3);
		}
	}

	fill(0);
	noStroke();
	for(var i = 0; i < particles.length; i++) {
		var particle = particles[i];
		ellipse(particle.getLocation().x, particle.getLocation().y, radius, radius);
	}

	particlePositions = pso.particles.map(particle => particle.getLocation());
	if(counter == 0 && running){
		pso.update();
	}
	counter = (counter + 1) % updateIt;
}

// === Tab: Particle ===
function Particle(location, velocity, fitnessValue) {
	this.velocity = velocity;

	/* fintness value of the current location */
	this.fitnessValue = fitnessValue;

	/* local best fitness value */
	this.localBestFitnessValue = fitnessValue;

	/* global best fitness value */
	this.globalBestFitnessValue = fitnessValue;

	/* current location */
	this.location = location;

	/* location of the best global fitness value */
	this.globalBestLocation = location;

	/* location of the best local fitness value */
	this.localBestLocation = location;

	this.getFitnessValue = function() {
		return this.fitnessValue;
	}

	this.getVelocity = function() {
		return this.velocity.copy();
	}

	this.getLocation = function() {
		return this.location.copy();
	}

	this.getGlobalBestFitnessValue = function() {
		return this.globalBestFitnessValue;
	}

	this.getLocalBestFitnessValue = function() {
		return this.localBestFitnessValue;
	}

	this.getGlobalBestLocation = function() {
		return this.globalBestLocation.copy();
	}

	this.getLocalBestLocation = function() {
		return this.localBestLocation.copy();
	}

	this.setGlobalBestFitnessValue = function(value) {
		this.globalBestFitnessValue = value;
	}

	this.setLocalBestFitnessValue = function(bestFitnessValue) {
		this.localBestFitnessValue = bestFitnessValue;
	}

	this.setLocalBestLocation = function(bestLocation) {
		this.localBestLocation = bestLocation;
	}

	this.setFitnessValue = function(fitnessValue) {
		this.fitnessValue = fitnessValue;
	}

	this.setGlobalBestLocation = function(location){
		this.globalBestLocation = location;
	}

	this.setLocation = function(location) {
		this.location = location;
	}

	this.setVelocity= function(velocity) {
		this.velocity = velocity;
	}
}

// === Tab: Circle ===
function Circle(center, radius) {
	this.center = center;
	this.radius = radius;

	this.contains = function(position) {
		return this.getCenter().sub(position).mag() <= this.radius;
	}

	this.getCenter = function() {
		return this.center.copy();
	}

	this.getRadius = function()  {
		return this.radius;
	}

	this.getClosestIntersection = function(p, q, r) {
		var intersectionPoints = this.getIntersection(p, q);

		if(intersectionPoints.length == 0) {
			return r;
		}

		var minDist = Number.MAX_VALUE;
		var iPoint = undefined;

		for(var i = 0; i < intersectionPoints.length; i++) {
			var ip = intersectionPoints[i];
			if(r.copy().sub(ip).mag() < minDist) {
				minDist = r.copy().sub(ip).mag();
				iPoint = ip;
			}
		}
		return iPoint;
	}

	this.getIntersection = function(p, q) {
		var pC = p.copy().sub(this.getCenter());
		var qC = q.copy().sub(this.getCenter());
		var x1 = pC.x;
		var y1 = pC.y;
		var x2 = qC.x;
		var y2 = qC.y;

		var dx = x2 - x1;
		var dy = y2 - y1;
		var dr = sqrt(dx * dx + dy * dy);
		var disc = x1 * y2 - x2 * y1;
		var D = this.radius * this.radius * dr * dr - disc*disc;
		var sign = dy < 0 ? -1 : 1;

		if(D == 0) {
			var x1 = (disc * dy + sign * dx * sqrt(D)) / (dr * dr);
			var y1 = (-disc * dx + abs(dy) * sqrt(D)) / (dr * dr);
			return [createVector(x1 + this.getCenter().x, y1 + this.getCenter().y)];
		}
		else if(D < 0) {
			return [];
		}
		else {
			var x1 = (disc * dy + sign * dx * sqrt(D)) / (dr * dr);
			var y1 = (-disc * dx + abs(dy) * sqrt(D)) / (dr * dr);
			var x2 = (disc * dy - sign * dx * sqrt(D)) / (dr * dr);
			var y2 = (-disc * dx - abs(dy) * sqrt(D)) / (dr * dr);

			return [createVector(x1 + this.getCenter().x, y1 + this.getCenter().y), createVector(x2 + this.getCenter().x, y2 + this.getCenter().y)];
		}
	}
}

// === Tab: PSO ===
function PSO(f, circle, maxAngle, minAngle) {
	/* PSO-Parameters */
	//this.swarmSize = 10 + 2;
	//this.swarmSize = 300;
	this.swarmSize = 40;
	this.maxIteration = 100;
	this.problemDimension = 2;
	this.K = 3;
	this.c1 = 1.193; // 1/2 + ln(2)
	this.c2 = 1.193;  // 1/2 + ln(2)

//	this.c1 = 1.193; // 1/2 + ln(2)
//	this.c2 = 0.5;  // 1/2 + ln(2)
	this.wUpperBound = 1.0;
	this.wLowerBound = 0.0;

	this.particles = [];
	this.circle = circle; 
	this.errorTol = 0.0001;
	this.gBest = Number.MAX_VALUE;
	this.gBestLocation = undefined;
	this.f = f;
	this.t = 0;
	this.maxAngle = maxAngle;
	this.minAngle = minAngle;

	this.getParticles = function() {
		return this.particles;
	}

	this.isCircle = function() {
		return angle >= 2*PI;
	}

	this.update = function() {
		var w;
		var err = 9999;

		if(this.t < this.maxIteration) {
			this.updateLocalBest();
			this.updateGlobalBest();

			//w = W_UPPERBOUND - (((double) t) / attributesPSO.maxIteration) * (W_UPPERBOUND - W_LOWERBOUND);
			w = this.wUpperBound - (this.t / this.maxIteration) * (this.wUpperBound - this.wLowerBound);
			//w = 1.0 - (this.t / this.maxIteration);
			//w = 0.721;

			for(var j = 0; j < this.particles.length; j++) {
				var particle = this.particles[j];
				var r1 = random();
				var r2 = random();
				var dirLocalBest = particle.getLocalBestLocation().copy().sub(particle.getLocation());
				var dirGlobalBest = particle.getGlobalBestLocation().copy().sub(particle.getLocation());

				var newVel = particle.getVelocity().copy().mult(w)
					.add(dirLocalBest.mult(r1 * this.c1))
					.add(dirGlobalBest.mult(r2 * this.c2))
				  .limit(this.circle.getRadius() / 5.0);

				var oldLocation = particle.getLocation();
				particle.setVelocity(newVel);
				particle.setLocation(particle.getLocation().add(particle.getVelocity()));

				// confinement
				if(!this.circle.contains(particle.getLocation())) {
					 particle.setVelocity(particle.getVelocity().mult(-0.5));
					 particle.setLocation(this.circle.getClosestIntersection(oldLocation, particle.getLocation(), particle.getLocation()));
				}
				particle.setFitnessValue(this.f(particle.getLocation()));
			}
		}
		this.t++;
	}

	/**
	 * Each particle informs k other particles about their global best solution.
	 */
	this.informParticlesAdative = function() {
		for(var i = 0; i < this.particles.length; i++) {
			var particle = this.particles[i];
			for(var j = 0; j < this.K; j++){
				var index = floor(random() * this.particles.length);
				var otherParticle = this.particles[index];
				var globalBest = particle.getGlobalBestFitnessValue();
				var otherGlobalBest = otherParticle.getGlobalBestFitnessValue();

				if(globalBest < otherGlobalBest) {
					otherParticle.setGlobalBestFitnessValue(globalBest);
					otherParticle.setGlobalBestLocation(particle.getGlobalBestLocation());
				}	
			}
		}
	}

	/**
	 * Each particle informs each other particle about their global best solution.
	 * Therefore, each particles knows the overall global best solution afterwards.
	 */
	this.informParticlesAll = function() {
		for(var i = 0; i < this.particles.length; i++) {
			var particle = this.particles[i];
			for(var j = 0; j < this.particles.length; j++) {
				var otherParticle = this.particles[j];
				var globalBest = particle.getGlobalBestFitnessValue();
				var otherGlobalBest = otherParticle.getGlobalBestFitnessValue();

				if(globalBest < otherGlobalBest) {
					otherParticle.setGlobalBestFitnessValue(globalBest);
					otherParticle.setGlobalBestLocation(particle.getGlobalBestLocation());
				}	
			}
		}
	}

	/**
	 * updates the best local value of each particle
	 */
	this.updateLocalBest = function(){
		for(var i = 0; i < this.particles.length; i++) {
			var particle = this.particles[i];
			if(particle.getFitnessValue() < particle.getLocalBestFitnessValue()) {
				particle.setLocalBestFitnessValue(particle.getFitnessValue());
				particle.setLocalBestLocation(particle.getLocation());	
			}

			if(particle.getLocalBestFitnessValue() < particle.getGlobalBestFitnessValue()) {
				particle.setGlobalBestFitnessValue(particle.getLocalBestFitnessValue());
				particle.setGlobalBestLocation(particle.getLocalBestLocation());	
			}
		}
	}

	/**
	 * 1) updates the best overall value of the PSO.
	 * 2) if the new best overall value is smaller than the old one,
	 *    particles inform each other about their best values and locations.
	 */
	this.updateGlobalBest = function() {
		var lastGBest = this.gBest;
		for(var i = 0; i < this.particles.length; i++) {
			var particle = this.particles[i];
			var localBest = particle.getGlobalBestFitnessValue();
			if(localBest < this.gBest){
				this.gBest = localBest;
				this.gBestLocation = particle.getGlobalBestLocation();
			}
		}	

		if(this.gBest >= lastGBest) {
			this.informParticlesAdative();
		}
	}

	/**
	 * Initializes the swarm on a circle.
	 */
	this.initializeSwarm = function() {		
		var k = 4;
		var parts = k*(k+1)/2;
		var swarmParts = (this.swarmSize-1) / parts;
		var angleDiff = this.maxAngle - this.minAngle;

		for(var j = 0; j < k; j++) {
			var numberOfPoints = swarmParts*(j+1);
			var randomStart = this.minAngle + random() * angleDiff / numberOfPoints;
			var deltaAngle = angleDiff / numberOfPoints;
			var angle = randomStart;
			var detaRadius = this.circle.getRadius() / k;

			for(var i = 0; i < numberOfPoints; i++) {				
				var x = cos(angle) * detaRadius*(j+1) + this.circle.getCenter().x;
				var y = sin(angle) * detaRadius*(j+1) + this.circle.getCenter().y;
				angle += deltaAngle;
				var location = createVector(x, y);

				if(this.circle.contains(location)) {
					var vDelta = random() * 2 * PI;
					var vMag = sqrt(random()) * this.circle.getRadius();
					var v = createVector(cos(vDelta), sin(vDelta)).setMag(vMag);
					var velocity = v.sub(location).mult(0.5).limit(this.circle.getRadius() / 5.0);

					var fitnessValue = this.f(location);
					var particle = new Particle(location, velocity, fitnessValue);
					this.particles.push(particle);
				}
			}
		}

		// add center pos
		var location = this.circle.getCenter();
		var vDelta = random() * 2 * PI;
		var vMag = sqrt(random()) * this.circle.getRadius();
		var v = createVector(cos(vDelta), sin(vDelta)).setMag(vMag);
		var velocity = v.sub(location).mult(0.5);
		var fitnessValue = this.f(location);
		var particle = new Particle(location, velocity, fitnessValue);
		this.particles.push(particle);
		this.updateGlobalBest();
		this.informParticlesAdative();
	}
}

