// === Tab: ParticleGroup ===
function ParticleGroup(particles) {
	this.particles = particles;
	this.gBest = Number.MAX_VALUE;
	this.gBestLocation = undefined;

	this.update = function() {
		this.updateLocalBest();
		//this.updateGlobalBest();
	}

	this.getGroupBest = function(){
		return this.gBest;
	}

	this.getGroupBestLocation = function() {
		return this.gBestLocation;
	}

	this.updateGlobalBest = function() {
		var bestIndex = this.getGloballyParticleIndex();
		if(this.particles[bestIndex].getBestFitnessValue() < this.gBest) {
			this.gBest = this.particles[bestIndex].getBestFitnessValue();
			this.gBestLocation = this.particles[bestIndex].getBestLocation();
		}
	}

	this.updateLocalBest = function(){
		for(var i = 0; i < this.particles.length; i++) {
			var particle = this.particles[i];
			if(particle.getFitnessValue() < particle.getBestFitnessValue()) {
				particle.setBestFitnessValue(particle.getFitnessValue());
				particle.setBestLocation(particle.getLocation());	
			}
		}
	}

	this.getGloballyParticleIndex = function() {
		var index = 0;
		var best = Number.MAX_VALUE;
		for(var i = 0; i < this.particles.length; i++) {
			var particle = this.particles[i];
			if(particle.getBestFitnessValue() < best) {
				index = i;
				best = particle.getBestFitnessValue();
			}
		}
		return index;
	}
}

// === Tab: Plotter ===
function Plotter(func, predicate, min, max) {
	this.func = func;
	this.predicate = predicate;
	this.max = max;
	this.min = min;

	this.draw = function(backgroundPlot) {
		backgroundPlot.colorMode(HSB, 360, 100, 100);
		backgroundPlot.noStroke();

		for(var x = 0; x < windowWidth; x++) {
			for(var y = 0; y < windowHeight; y++) {
				var vec = createVector(x, y);
				if(predicate(vec)) {
					var val = func(vec);
					var val = func(vec);
					var c = (150+((val-this.min) * 360) / (this.max - this.min))%360;
					backgroundPlot.stroke(c, 80, 80);
					backgroundPlot.point(x, y);
				}
			}
		}
	}
}

// === Tab: CircleSector ===
function CircleSector(center, radius, minAngle, maxAngle) {
	this.center = center;
	this.radius = radius;
	this.minAngle = minAngle;
	this.maxAngle = maxAngle;

	this.contains = function(position) {
		if(this.getCenter().sub(position).mag() <= this.radius) {
			var delta = this.angleTo(position);
			return delta >= this.minAngle && delta <= this.maxAngle;
		}
		return false;
	}

	/**
	 * 
	 * Computes the angle between the x-axis through the given Point "center" and this.
	 * Result is in interval (0,2*PI) according to standard math usage.
	 */
	this.angleTo = function(position) {
		var center = this.getCenter();
		var at2 = atan2(position.y - center.y, position.x - center.x);

		if (at2 < 0.0) {
			at2 = PI * 2 + at2;
		}

		return at2;
	}

	this.getIntersection = function(p, q) {
		var allIntersectionPoints = [];
		var p1 = this.getCenter();
		var p2 = createVector(cos(this.minAngle) * this.getRadius(), sin(this.minAngle) * this.getRadius());
		var q1 = this.getCenter();
		var q2 = createVector(cos(this.maxAngle) * this.getRadius(), sin(this.maxAngle) * this.getRadius());

		if(this.intersects(p1, p2, p, q)) {
			allIntersectionPoints.push(this.lineLineIntersection(p1, p2, p, q));
		}

		if(this.intersects(q1, q2, p, q)) {
			allIntersectionPoints.push(this.lineLineIntersection(q1, q2, p, q));
		}

		var circle = new Circle(this.getCenter(), this.getRadius());
		var intersectionPoints = circle.getIntersection(p, q);
		for(var i = 0; i < intersectionPoints.length; i++) {
			var point = intersectionPoints[i];
			var delta = this.angleTo(point);
			if(delta >= this.minAngle && delta <= this.maxAngle) {
				allIntersectionPoints.push(point);
			}
		}

		return allIntersectionPoints;
	}

	this.lineLineIntersection = function(p1, p2, q1, q2) {
		var d = (p1.x - p2.x) * (q1.y - q2.y) - (p1.y - p2.y) * (q1.x - q2.x);
		var x = ((p1.x * p2.y - p1.y - p2.x) * (q1.x - q2.x) - (p1.x - p2.x) * (q1.x * q2.y - q1.y * q2.x)) / d;
		var y = ((p1.x * p2.y - p1.y * p2.x) * (q1.y - q2.y) - (p1.y - p2.y) * (q1.y * q2.y - q1.y * q2.x)) / d;
		return createVector(x, y);
	}

	this.getClosestIntersection = function(p, q, r) {
		var intersectionPoints = this.getIntersection(p, q);

		if(intersectionPoints.length == 0) {
			return r;
		}

		var minDist = Number.MAX_VALUE;
		var iPoint = undefined;

		for(var i = 0; i < intersectionPoints.length; i++) {
			var ip = intersectionPoints[i];
			if(r.copy().sub(ip).mag() < minDist) {
				minDist = r.copy().sub(ip).mag();
				iPoint = ip;
			}
		}
		return iPoint;
	}

	this.intersects = function(p1, p2, q1, q2) {
		return (this.ccw(p1, q1, q2) != this.ccw(p2, q1, q2)) && (this.ccw(p1, p2, q1) != this.ccw(p1, p2, q2));
	}

	/**
	 * Calculate the counter clockwise result for the three given points.
	 */
	this.ccw = function(p1, p2, p3) {
		return ((p2.x - p1.x) * (p3.y - p1.y) - (p2.y - p1.y) * (p3.x - p1.x)) < 0;
	}

	this.getCenter = function() {
		return this.center.copy();
	}

	this.getRadius = function()  {
		return this.radius;
	}
}

